<script setup lang="ts">
import {ref,watch,computed} from 'vue';
import {useRouter} from 'vue-router';
import {resultApi} from '@/api/result.api';
import {extractApiErrorMessage} from '@/api/http';
import {useAuthStore} from '@/stores/auth.store';
import type {TaskResultBundle} from '@/types/result.types';
import UserTaskReportPanel from './export/UserTaskReportPanel.vue';
import KnowledgeSubmitDialog from './KnowledgeSubmitDialog.vue';
const props=defineProps<{taskId:string;initialRunId?:string}>();
const auth=useAuthStore(),router=useRouter();
const bundle=ref<TaskResultBundle|null>(null),selected=ref(props.initialRunId||''),error=ref(''),loading=ref(false),reports=ref(false),knowledge=ref(false);
const canReport=computed(()=>auth.hasPermission('report_read'));
const canKnowledge=computed(()=>bundle.value?.execution?.effective_status==='accepted'&&auth.hasPermission('knowledge_candidate_submit')&&
  [bundle.value.execution.created_by,bundle.value.execution.reviewed_by].includes(auth.userId));
const sampleName=(id:string)=>bundle.value?.execution?.snapshot.task_context?.selected_samples?.find(s=>s.id===id)?.label||id;
const kindLabel=(kind:string)=>({inspection_requirement:'产品检测要求',method_condition:'试验方法 / 条件',body_clause:'参考正文'} as Record<string,string>)[kind]||'用途待核对';
async function load(){loading.value=true;error.value='';try{
  const response=await resultApi.summary(props.taskId,selected.value==='legacy'?{legacy_only:true}:selected.value?{execution_run_id:selected.value}:undefined);
  bundle.value=response.data.data;selected.value=bundle.value.selection.execution_run_id||(bundle.value.auxiliary?'legacy':'');
}catch(cause){error.value=extractApiErrorMessage(cause,'任务结果暂时无法读取');}finally{loading.value=false;}}
watch(()=>props.taskId,()=>{selected.value=props.initialRunId||'';void load();},{immediate:true});
</script>
<template><section class="unified-result" v-loading="loading"><header><div><p>任务结果 / 版本与范围</p><h2>{{ bundle?.scope.label||'任务结果' }}</h2><small>产品整体未评定；项目符合性与风险研判分别核对。</small></div><div class="actions"><el-button @click="load">刷新结果</el-button><el-button v-if="bundle?.can_export&&canReport" type="primary" @click="reports=true">导出此版本报告</el-button></div></header><el-alert v-if="error" :title="error" type="warning" :closable="false"/>
<template v-if="bundle"><div class="version-row"><span>读取版本</span><el-select v-model="selected" @change="load"><el-option v-for="(run,index) in bundle.execution_versions" :key="run.id" :value="run.id" :label="`执行 ${bundle.execution_versions.length-index} · 版本 ${run.row_version} · ${run.status==='accepted'?'历史已复核':run.status==='draft'?'待复核':run.status}`"/><el-option v-if="bundle.auxiliary" label="仅查看图片 / 历史辅助记录" value="legacy"/></el-select><el-tag effect="plain">{{ bundle.scope.stage==='reviewed_selected_items'?'选定项目已复核':bundle.scope.stage==='needs_reassessment'?'当前来源需重新核验':'辅助 / 待复核记录' }}</el-tag></div><el-alert :title="bundle.scope.boundary" type="info" :closable="false"/>
<template v-if="bundle.execution"><el-alert v-if="bundle.execution.current_source_issues.length" :title="bundle.execution.current_source_issues.join('；')" type="warning" :closable="false"/><el-table :data="bundle.execution.evaluation.checks"><el-table-column label="样品" min-width="140"><template #default="{row}">{{ sampleName(row.sample_id) }}</template></el-table-column><el-table-column label="条款用途" width="150"><template #default="{row}">{{ kindLabel(row.candidate_type) }}</template></el-table-column><el-table-column prop="indicator" label="项目" min-width="170"/><el-table-column prop="standard_no" label="标准" min-width="150"/><el-table-column prop="clause_no" label="条款" width="80"/><el-table-column label="项目状态" width="150"><template #default="{row}">{{ ({pass:'本项目符合',fail:'本项目不符合',missing:'缺少观测',uncertain:'不确定',manual_required:'需人工核对'} as Record<string,string>)[row.status]||'尚不完整' }}</template></el-table-column></el-table><div class="actions"><el-button @click="router.push(`/app/tasks/${taskId}`)">查看来源与独立复核</el-button><el-button v-if="canKnowledge" @click="knowledge=true">从此执行版本提出知识候选</el-button></div></template>
<div v-if="bundle.auxiliary" class="bounded-note"><strong>图片 / 历史记录独立保留</strong><p>{{ bundle.auxiliary.notice }}</p></div><section class="risk-summary"><h3>同一执行版本的风险研判</h3><el-button v-if="bundle.execution?.effective_status==='accepted'&&auth.hasPermission('quality')" @click="router.push({path:'/app/risk-assessments',query:{execution_run_id:bundle.execution.id}})">将此版本用于风险研判</el-button><p v-if="!bundle.risks.length">暂无本版本可引用的风险研判；项目通过不自动形成风险等级。</p><article v-for="risk in bundle.risks" :key="risk.id"><strong>{{ risk.risk_type||'风险线索' }} · 第 {{ risk.version }} 版</strong><span>{{ risk.effective_status==='accepted'?'已独立确认':'待复核 / 来源需核验' }} · {{ ({unknown:'等级待确认',low:'低风险',medium:'中风险',high:'高风险',critical:'严重风险'} as Record<string,string>)[risk.risk_level] }}</span><p>{{ risk.recommendations.join('；') }}</p><small v-if="risk.probability==null">发生概率未校准。</small></article></section>
</template><el-drawer v-model="reports" title="当前版本的报告" size="min(780px, 100vw)" append-to-body><UserTaskReportPanel v-if="reports&&bundle" :task-id="taskId" :execution-run-id="bundle.selection.execution_run_id||undefined" :legacy-only="bundle.selection.legacy_only" embedded/></el-drawer><KnowledgeSubmitDialog v-if="bundle?.execution" v-model="knowledge" source-kind="inspection_execution" :source-id="bundle.execution.id"/></section></template>
<style scoped>.unified-result{display:grid;gap:18px;padding:24px;margin-bottom:22px;background:#fff;border:1px solid #dbe5f2;border-top:4px solid #2463bb;border-radius:12px}.unified-result header{display:flex;justify-content:space-between;gap:22px}.unified-result header p{margin:0;color:#2563eb;font-size:12px}.unified-result h2{margin:6px 0;color:#183451;font-size:24px}.unified-result small,.risk-summary p{color:#64748b}.actions{display:flex;gap:8px;flex-wrap:wrap}.version-row{display:flex;gap:14px;align-items:center;flex-wrap:wrap}.version-row .el-select{min-width:280px}.bounded-note{padding:16px;border-left:3px solid #94a3b8;background:#f7f9fc}.bounded-note p{margin-bottom:0;color:#64748b}.risk-summary h3{font-size:15px}.risk-summary article{display:grid;gap:8px;padding:15px;border:1px solid #dbe5f2;border-radius:10px}@media(max-width:760px){.unified-result header{flex-direction:column}.unified-result{padding:16px}.version-row .el-select{min-width:0;width:100%}}</style>
